    pos={v:[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v] for v in range(1,10)}
    # The 1/2 motif uses their horizontal separation: 1 extends right by that
    # distance and is copied one row above the far end; 2 extends left by twice it.
    if pos[1] and pos[2]:
        r1,c1=pos[1][0]; r2,c2=pos[2][0]
