        if c2>c1:
            for c in range(c1+1,min(c2+1,len(grid[0]))):
                if out[r1][c]==0: out[r1][c]=5
            if r1>0: out[r1-1][c2]=1
            left=max(0,c2-2*dx)
            for c in range(left+1,c2):
                if out[r2][c]==0: out[r2][c]=5
            out[r2][left]=2
    # Each 6 marker makes a six-cell upward stroke, with 6 at its far endpoint.
    for r,c in pos[6]:
        end=max(0,r-6)
        for rr in range(end+1,r):
            if out[rr][c]==0: out[rr][c]=5
        out[end][c]=6
    # 3 makes a three-cell downward stroke, ending in a copy of itself.
    for r,c in pos[3]:
        end=min(len(grid)-1,r+3)
        for rr in range(r+1,end):
            if out[rr][c]==0: out[rr][c]=5
        out[end][c]=3
    return out
