    if positions[1] and positions[2]:
        r, c = positions[1][0]
        _, c2 = positions[2][0]
        distance = abs(c2 - c)
        if c2 > c:
            for j in range(c + 1, min(c + distance + 1, len(grid[0]))):
                out[r][j] = 5
            if r > 0 and c + distance < len(grid[0]):
                out[r - 1][c + distance] = 1
            # Color 2 extends left twice that horizontal spacing.
            r2, c2 = positions[2][0]
            end = max(0, c2 - 2 * distance)
            for j in range(end + 1, c2):
                out[r2][j] = 5
            out[r2][end] = 2
    # Color 6 extends six cells upward, with a 6 at the far endpoint.
    for r, c in positions[6]:
        end = max(0, r - 6)
        for i in range(end + 1, r):
            out[i][c] = 5
        out[end][c] = 6
    # Color 3 extends three cells downward, with a 3 at the far endpoint.
    for r, c in positions[3]:
        end = min(len(grid) - 1, r + 3)
        for i in range(r + 1, end):
            out[i][c] = 5
        out[end][c] = 3
    return out
