def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pos = {v: [(r, c) for r, row in enumerate(grid) for c, x in enumerate(row) if x == v]
           for v in (1, 2, 3, 6)}
    # For a 1/2 pair, the row separation sets the ray length: 1 goes right
    # by that many cells; 2 goes left by twice that many cells.
    if pos[1] and pos[2]:
        (r1, c1), (r2, c2) = pos[1][0], pos[2][0]
        d = abs(r2 - r1)
        if c2 > c1:
            for c in range(c1 + 1, min(c1 + d + 1, w)):
                out[r1][c] = 5
            tip = c1 + d
            if r1 > 0 and tip < w:
                out[r1 - 1][tip] = 1
            left = max(0, c2 - 2 * d)
            out[r2][left] = 2
            for c in range(left + 1, c2):
                out[r2][c] = 5
    # 6 extends upward, with 5s and a copied endpoint at row 1.
    for r, c in pos[6]:
        if r > 1:
            for rr in range(2, r):
                out[rr][c] = 5
            out[1][c] = 6
    # 3 extends three cells downward, with a copied 3 at the end.
    for r, c in pos[3]:
        end = min(r + 3, h - 1)
        for rr in range(r + 1, end):
            out[rr][c] = 5
        if end > r:
            out[end][c] = 3
    return out
